#!/usr/bin/env python3
"""Snapshot of static/js/topology-activity.js — who's to blame when the board paints a route.

This module is the birthplace of the "absence drawn as normal" defect class,
and of four attribution fixes: a dying cell isn't blamed on the agent
(948ad8d), a client dropout is yellow, not red (7baefad), a route
distinguishes assigned/confirmed/unverified (ea9baf0), a spike badge from
three errors an hour (f7cf791). VALUES are pinned: an incident's kind and its
reason, health ("failed" only for failed/upstream_timeout — upstream_disconnected
and blocked give "degraded", as-is), four sources of proxy activity in
priority order, the "?" status (not an incident, but painted as an error on
the recent branch — as-is), the 30s/120s/59.5s/3-errors thresholds, timeout
priority (provider > agent defaults > 3600), a route row's three-way state.

Pins live as data in PINS: (id, setup, expression, expected JSON, message).
Each pin runs in its own try/catch block: an exception becomes the value
{"__threw": "..."}, never silence. Time is frozen (Date.now = 1700000100s).
The module is loaded FOR REAL together with
state/constants/i18n/utils/model-meta/topology-proxies/polling; the
remaining neighbors are stubs (_js_harness.mjs).

Run: python3 scripts/test_js_topology_activity.py
"""
import json
import os
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(Path(__file__).resolve().parent))
from _node import find_node, node_search_paths  # noqa: E402

STUBS = ("topology-render,topology-nodes,topology-modals,cables,routers,charts,remote-cells,cloud,history,dialogs,"
         "llama-edit,form,favorites,config-locator,system-panels,onboarding,topology-dnd,canvas,"
         "command-preview,memory,usage-stats,dialog-llamas,models-page,system-page,onboarding-tours")

PREAMBLE = r"""
import "./_js_globals.mjs";
import { pathToFileURL } from "node:url";
const st = await import(pathToFileURL(process.env.JS_ROOT + "/state.js").href);
st.setState({ config: {} });
st.setTopology({ proxies: [], clients: [], routers: [], assignments: {} });
Date.now = () => 1_700_000_100_000;
const m = await import(pathToFileURL(process.env.JS_ROOT + "/topology-activity.js").href);
const ui = st.ui;
const reset = () => { st.setState({ config: {} }); st.setTopology({ proxies: [], clients: [], routers: [], assignments: {} });
  ui.latestSystemMonitor = null; ui.routeErrHour = null; };
const norm = (s) => String(s).replace(/\s+/g, " ").trim();
const out = {};
"""

